<script setup lang="ts">
import { computed, ref, watch, defineComponent } from 'vue';
import type { PropType, VNodeChild } from 'vue';
import type { TableColumn, TableChange } from './table-types';
import Checkbox from './Checkbox.vue';
import './styles/theme.css';
import './styles/table.css';
import './styles/button.css';
type Row = Record<string, unknown>;
const props = withDefaults(defineProps<{ columns: TableColumn[]; dataSource: Row[]; rowKey: string | ((record: Row) => string | number); loading?: boolean; emptyText?: string; mode?: 'client' | 'server'; pageSize?: number; currentPage?: number; total?: number; pageSizeOptions?: number[]; rowSelection?: { selectedRowKeys: (string | number)[]; onChange?: (keys: (string | number)[], rows: Row[]) => void } }>(), { emptyText: '暂无数据', mode: 'client', pageSize: 8, pageSizeOptions: () => [8, 16, 32] });
const emit = defineEmits<{ change: [change: TableChange]; 'update:currentPage': [page: number]; selectionChange: [keys: (string | number)[], rows: Row[]] }>();
const internalPage = ref(1); const activeSize = ref(props.pageSize); const sort = ref<TableChange['sort']>(); const filters = ref<Record<string, string>>({});
const page = computed(() => props.currentPage ?? internalPage.value);
watch(() => props.pageSize, value => { activeSize.value = value; });
const key = (row: Row) => typeof props.rowKey === 'function' ? props.rowKey(row) : String(row[props.rowKey]);
const rows = computed(() => { if (props.mode === 'server') return props.dataSource; let next = [...props.dataSource]; for (const [key, value] of Object.entries(filters.value)) { const column = props.columns.find(item => item.key === key); if (value && column) next = next.filter(record => column.onFilter?.(value, record) ?? String(record[String(column.dataIndex)] ?? '') === value); } const order = sort.value; if (order) { const column = props.columns.find(item => item.key === order.key); next.sort((left, right) => { const result = typeof column?.sorter === 'function' ? column.sorter(left, right) : String(left[String(column?.dataIndex)] ?? '').localeCompare(String(right[String(column?.dataIndex)] ?? ''), 'zh-CN', { numeric: true }); return order.direction === 'asc' ? result : -result; }); } return next; });
const totalRows = computed(() => props.mode === 'server' ? props.total ?? props.dataSource.length : rows.value.length);
const totalPages = computed(() => Math.max(1, Math.ceil(totalRows.value / activeSize.value)));
const visible = computed(() => props.mode === 'client' ? rows.value.slice((page.value - 1) * activeSize.value, page.value * activeSize.value) : rows.value);
function change(next: number) { if (props.currentPage === undefined) internalPage.value = next; emit('update:currentPage', next); emit('change', { page: next, pageSize: activeSize.value, sort: sort.value, filters: { ...filters.value } }); }
function order(column: TableColumn) { sort.value = { key: column.key, direction: sort.value?.key === column.key && sort.value.direction === 'asc' ? 'desc' : 'asc' }; change(1); }
function filter(event: Event, column: TableColumn) { filters.value = { ...filters.value, [column.key]: (event.target as HTMLSelectElement).value }; change(1); }
function selection(keys: (string | number)[]) { const rows = props.dataSource.filter(row => keys.includes(key(row))); props.rowSelection?.onChange?.(keys, rows); emit('selectionChange', keys, rows); }
function selectPage(checked: boolean) { const pageKeys = visible.value.map(key); selection(checked ? [...new Set([...(props.rowSelection?.selectedRowKeys ?? []), ...pageKeys])] : (props.rowSelection?.selectedRowKeys ?? []).filter(key => !pageKeys.includes(key))); }
function selectRow(row: Row, checked: boolean) { const selected = props.rowSelection?.selectedRowKeys ?? []; selection(checked ? [...new Set([...selected, key(row)])] : selected.filter(value => value !== key(row))); }
function resize(event: Event) { activeSize.value = Number((event.target as HTMLSelectElement).value); change(1); }
const RenderCell = defineComponent({ props: { content: { type: [String, Number, Object, Array, Boolean] as PropType<VNodeChild> } }, setup: props => () => props.content });
</script>
<template><div class="at-table-shell"><div class="at-table-scroll"><table class="at-table"><thead><tr><th v-if="rowSelection" class="at-table__selection"><Checkbox aria-label="选择本页全部行" :model-value="visible.length > 0 && visible.every(row => rowSelection?.selectedRowKeys.includes(key(row)))" @update:model-value="selectPage" /></th><th v-for="column in columns" :key="column.key" :style="{ width: typeof column.width === 'number' ? `${column.width}px` : column.width, textAlign: column.align }"><div class="at-table__heading"><slot name="headerCell" :column="column"><span>{{ column.title }}</span></slot><button v-if="column.sorter" type="button" class="at-table__sort" :aria-label="`按${column.title}排序`" @click="order(column)">↕</button><select v-if="column.filters?.length" class="at-table__filter" :aria-label="`筛选${column.title}`" :value="filters[column.key] ?? ''" @change="filter($event, column)"><option value="">全部</option><option v-for="filter in column.filters" :key="filter.value" :value="filter.value">{{ filter.label }}</option></select></div></th></tr></thead><tbody><tr v-if="loading || !visible.length"><td :colspan="columns.length + (rowSelection ? 1 : 0)"><div class="at-table__status" :aria-busy="loading"><template v-if="loading"><span class="at-spinner" />正在加载数据…</template><slot v-else name="empty">{{ emptyText }}</slot></div></td></tr><tr v-for="(record, index) in (loading ? [] : visible)" :key="key(record)"><td v-if="rowSelection" class="at-table__selection"><Checkbox :aria-label="`选择第 ${index + 1} 行`" :model-value="rowSelection.selectedRowKeys.includes(key(record))" @update:model-value="selectRow(record, $event)" /></td><td v-for="column in columns" :key="column.key" :style="{ textAlign: column.align }"><slot name="bodyCell" :column="column" :record="record" :index="index" :value="record[String(column.dataIndex)]"><RenderCell v-if="column.render" :content="column.render(record[String(column.dataIndex)], record, index)" /><template v-else>{{ record[String(column.dataIndex)] ?? '' }}</template></slot></td></tr></tbody></table></div><div class="at-table__pagination"><span>共 {{ totalRows }} 条</span><div class="at-table__page-controls"><label>每页 <select :value="activeSize" @change="resize"><option v-for="size in pageSizeOptions" :key="size" :value="size">{{ size }}</option></select> 条</label><button type="button" :disabled="page <= 1" @click="change(page - 1)">上一页</button><span class="at-table__page">{{ page }} / {{ totalPages }}</span><button type="button" :disabled="page >= totalPages" @click="change(page + 1)">下一页</button></div></div></div></template>
